//! Chrome-156 control for the core DOM runtime's edge cases (consolidation P5-cov).
//!
//! `tests/fixtures/rtdom_core_chrome156.json` is generated by
//! `scripts/rtdom-core-chrome-control.mjs` (Chrome for Testing 156 via playwright-core):
//! - `documents`: every case's html5lib-format tree dump must equal Chrome's through BOTH
//!   parsers — upstream html5ever (`Tree::parse` / `set_inner_html`) and the UTF-16
//!   tokenizer fork (`Tree::parse_with_source_positions` /
//!   `create_contextual_fragment_utf16`). The cases walk the fork's states: NUL handling,
//!   attribute / comment / DOCTYPE / character-reference edge cases, end of input in each
//!   state, CDATA in foreign content, and the tree-builder hooks the UTF-16 path delegates;
//! - `selectors`: validity (`query_selector_all_checked`) and `matches` through the string
//!   and UTF-16 (`matches_units`) selector APIs for every element;
//! - `probes`: scripted DOM API results (`CharacterData`, Attr nodes, `insertAdjacentElement`,
//!   `toggleAttribute`, names and namespaces, `:*-of-type` across namespaces, serialization,
//!   `removeAttribute`, contextual-fragment `is`) rebuilt through the Tree API.
use serde_json::{json, Value};
use turbo_dom::rtdom::serialize::serialize_inner;
use turbo_dom::rtdom::tree::{Namespace, NodeType};
use turbo_dom::{Handle, Tree};

const FIXTURE: &str = include_str!("fixtures/rtdom_core_chrome156.json");

/// Recorded Chrome answers rtdom does not give yet, each with its issue; skipped by the
/// assertions until the fixing commit removes them here. (turbo-dom#92, RCDATA-context
/// fragments dropping U+0000, is fixed.)
