fn fixture() -> Value {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    assert!(fixture["chrome"].as_str().unwrap().starts_with("156."));
    fixture
}

/// html5lib tree dump of `parent`'s children over the public Tree API — the format
/// the control's JS dumper writes from Chrome's DOM.
fn dump(tree: &Tree, parent: Handle) -> String {
    fn walk(tree: &Tree, node: Handle, depth: usize, out: &mut Vec<String>) {
        let indent = |depth: usize| format!("| {}", "  ".repeat(depth));
        match tree.node_type(node) {
            NodeType::Element => {
                let ns = match tree.namespace(node) {
                    Namespace::Svg => "svg ",
                    Namespace::MathMl => "math ",
                    _ => "",
                };
                out.push(format!(
                    "{}<{ns}{}>",
                    indent(depth),
                    tree.local_name(node).unwrap()
                ));
                let mut attrs = Vec::new();
                tree.for_each_attr_full(node, |prefix, name, value| {
                    let shown = if prefix.is_empty() {
                        name.to_string()
                    } else {
                        format!("{prefix} {name}")
                    };
                    attrs.push((shown, value.to_string()));
                });
                attrs.sort();
                for (name, value) in attrs {
                    out.push(format!("{}{name}=\"{value}\"", indent(depth + 1)));
                }
                for child in tree.children(node) {
                    walk(tree, child, depth + 1, out);
                }
            }
            NodeType::Fragment => {
                out.push(format!("{}content", indent(depth)));
                for child in tree.children(node) {
                    walk(tree, child, depth + 1, out);
                }
            }
            NodeType::Text => out.push(format!(
                "{}\"{}\"",
                indent(depth),
                tree.node_value(node).unwrap()
            )),
            NodeType::Comment => out.push(format!(
                "{}<!-- {} -->",
                indent(depth),
                tree.node_value(node).unwrap()
            )),
            NodeType::Doctype => {
                let name = tree.doctype_name(node).unwrap();
                let public = tree.doctype_public_id(node).unwrap();
                let system = tree.doctype_system_id(node).unwrap();
                out.push(if public.is_empty() && system.is_empty() {
                    format!("{}<!DOCTYPE {name}>", indent(depth))
                } else {
                    format!(
                        "{}<!DOCTYPE {name} \"{public}\" \"{system}\">",
                        indent(depth)
                    )
                });
            }
            other => panic!("unexpected {other:?} in a parsed tree"),
        }
    }
    let mut out = Vec::new();
    for child in tree.children(parent) {
        walk(tree, child, 0, &mut out);
    }
    out.join("\n")
}

fn context_element(tree: &mut Tree, context: &str) -> Handle {
    match context.split_once(' ') {
        Some(("svg", local)) => tree.create_element_ns(local, Namespace::Svg),
        Some(("math", local)) => tree.create_element_ns(local, Namespace::MathMl),
        _ => tree.create_element(context),
    }
}

#[test]
fn documents_match_chrome_through_both_parsers() {
    let fixture = fixture();
    let cases = fixture["documents"].as_array().unwrap();
    assert!(
        cases.len() >= 80,
        "fixture shrank: {} documents",
        cases.len()
    );
    let mut failures = Vec::new();
    for case in cases {
        let id = case["id"].as_str().unwrap();
        if OPEN_DOCUMENTS.contains(&id) {
            continue;
        }
        let html = case["html"].as_str().unwrap();
        let want = case["dump"].as_str().unwrap();
        let units: Vec<u16> = html.encode_utf16().collect();
        let results = if let Some(context) = case["context"].as_str() {
            let mut tree = Tree::parse("");
            let element = context_element(&mut tree, context);
            tree.set_inner_html(element, html);
            let upstream = dump(&tree, element);
            let element = context_element(&mut tree, context);
            let fragment = tree.create_contextual_fragment_utf16(element, &units, false);
            [
                ("set_inner_html", upstream),
                ("create_contextual_fragment_utf16", dump(&tree, fragment)),
            ]
        } else {
            let upstream = Tree::parse(html);
            let positioned = Tree::parse_with_source_positions(html);
            [
                ("parse", dump(&upstream, upstream.root())),
                (
                    "parse_with_source_positions",
                    dump(&positioned, positioned.root()),
                ),
            ]
        };
        for (path, got) in results {
            if got != want {
                failures.push(format!(
                    "{id} via {path}:\n--- Chrome\n{want}\n--- rtdom\n{got}"
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

/// Elements in document order (Chrome walks `children`).
fn elements(tree: &Tree) -> Vec<Handle> {
    fn walk(tree: &Tree, node: Handle, out: &mut Vec<Handle>) {
        for child in tree.children(node) {
            if tree.node_type(child) == NodeType::Element {
                out.push(child);
                walk(tree, child, out);
            }
        }
    }
    let mut out = Vec::new();
    walk(tree, tree.root(), &mut out);
    out
}

#[test]
fn selectors_match_chrome_through_string_and_utf16_apis() {
    let fixture = fixture();
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in fixture["selectors"].as_array().unwrap() {
        let html = format!(
            "<!DOCTYPE html><html><head></head><body>{}</body></html>",
            case["html"].as_str().unwrap()
        );
        let tree = Tree::parse(&html);
        let els = elements(&tree);
        let tags: Vec<&str> = case["elements"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(
            els.iter()
                .map(|&h| tree.local_name(h).unwrap())
                .collect::<Vec<_>>(),
            tags,
            "{}: element list",
            case["id"]
        );
        for row in case["selectors"].as_array().unwrap() {
            checked += 1;
            let selector = row["selector"].as_str().unwrap();
            if OPEN_SELECTORS.contains(&selector) {
                continue;
            }
            let units: Vec<u16> = selector.encode_utf16().collect();
            let valid = row["valid"].as_bool().unwrap();
            if tree.query_selector_all_checked(selector).is_ok() != valid {
                failures.push(format!("{selector:?}: validity, Chrome {valid}"));
                continue;
            }
            if !valid {
                continue;
            }
            for (i, want) in row["matches"].as_str().unwrap().chars().enumerate() {
                let want = want == '1';
                if tree.matches(els[i], selector) != want {
                    failures.push(format!(
                        "{selector:?}: matches <{}>#{i}, Chrome {want}",
                        tags[i]
                    ));
                }
                if tree.matches_units(els[i], &units) != want {
                    failures.push(format!(
                        "{selector:?}: matches_units <{}>#{i}, Chrome {want}",
                        tags[i]
                    ));
                }
            }
        }
    }
    assert!(checked >= 40, "fixture shrank: {checked} selectors");
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

fn probe(fixture: &Value, id: &str) -> Value {
    fixture["probes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|p| p["id"] == id)
        .unwrap_or_else(|| panic!("probe {id} missing"))["values"]
        .clone()
}

fn value(tree: &Tree, node: Handle) -> String {
    tree.node_value(node).unwrap()
}

#[test]
fn character_data_methods_match_chrome() {
    let mut tree = Tree::parse("");
    let t = tree.create_text_node("hello");
    let p = tree.create_element("p");
    tree.append_child(p, t);
    tree.insert_data(t, 1, "XY");
    let after_insert = value(&tree, t);
    tree.delete_data(t, 0, 2);
    let after_delete = value(&tree, t);
    tree.append_data(t, "!");
    let after_append = value(&tree, t);
    tree.replace_data(t, 1, 3, "-");
    let after_replace = value(&tree, t);
    let sub = tree.substring_data(t, 1, 2);
    let tail = tree.split_text(t, 2);
    let comment = tree.create_comment("abc");
    tree.append_data(comment, "d");
    tree.delete_data(comment, 0, 1);
    let got = json!({
        "afterInsert": after_insert,
        "afterDelete": after_delete,
        "afterAppend": after_append,
        "afterReplace": after_replace,
        "sub": sub,
        "head": value(&tree, t),
        "tail": value(&tree, tail),
        "tailIsNextSibling": tree.next_sibling(t) == Some(tail),
        "parentChildren": tree.children(p).len(),
        "comment": value(&tree, comment),
    });
    assert_eq!(got, probe(&fixture(), "character_data"));
}

#[test]
fn attr_nodes_match_chrome() {
    let mut tree = Tree::parse("");
    let el = tree.create_element("div");
    let other = tree.create_element("span");
    let a = tree.create_attribute(None, "title", "v");
    assert_eq!(tree.set_attribute_node(el, a), Ok(None));
    let again = tree.set_attribute_node(el, a);
    let ns = tree.create_attribute(Some("urn:x"), "p:local", "");
    tree.set_attribute_node(el, ns).unwrap();
    let remove_foreign = match tree.remove_attribute_node(other, a) {
        Ok(_) => "ok",
        Err(name) => name,
    };
    tree.set_text_content(a, "via-textContent");
    let after_text_content = tree.get_attribute(el, "title").map(str::to_owned);
    tree.set_node_value(a, "via-nodeValue");
    let after_node_value = tree.get_attribute(el, "title").map(str::to_owned);
    let detached = tree.create_attribute(None, "data-d", "");
    tree.set_attribute_value(detached, "dv");
    let got = json!({
        "againIsSame": again == Ok(Some(a)),
        "removeForeign": remove_foreign,
        "afterTextContent": after_text_content,
        "afterNodeValue": after_node_value,
        "localName": tree.local_name(ns),
        "name": tree.qualified_name(ns),
        "prefix": tree.prefix(ns),
        "namespaceURI": tree.namespace_uri(ns),
        "htmlAttrNamespace": tree.namespace_uri(a),
        "htmlAttrPrefix": tree.prefix(a),
        "detachedValue": tree.node_value(detached),
        "detachedOwner": tree.attribute_owner(detached).map(Handle::raw),
    });
    assert_eq!(got, probe(&fixture(), "attr_nodes"));
}

#[test]
fn node_value_setter_is_a_no_op_on_elements_like_chrome() {
    let mut tree = Tree::parse("");
    let el = tree.create_element("div");
    tree.set_text_content(el, "x");
    tree.set_node_value(el, "ignored");
    let got = json!({ "text": tree.text_content(el), "nodeValue": tree.node_value(el) });
    assert_eq!(got, probe(&fixture(), "node_value_on_elements"));
}

#[test]
fn insert_adjacent_element_matches_chrome() {
    let mut tree = Tree::parse("");
    let host = tree.create_element("div");
    let i = tree.create_element("i");
    tree.append_child(host, i);
    let wrapper = tree.create_element("section");
    tree.append_child(wrapper, host);
    let mut inserted = Vec::new();
    for position in [
        "beforebegin",
        "afterbegin",
        "beforeend",
        "afterend",
        "AfterBegin",
    ] {
        let el = tree.create_element("b");
        tree.set_attribute(el, "id", position);
        inserted.push(tree.insert_adjacent_element(host, position, el));
    }
    let detached = tree.create_element("div");
    let u = tree.create_element("u");
    let before = tree.insert_adjacent_element(detached, "beforebegin", u);
    let after = tree.insert_adjacent_element(detached, "afterend", u);
    // Chrome throws SyntaxError for an unknown position; rtdom reports `false` and
    // leaves the tree unchanged (the binding raises the exception).
    let u2 = tree.create_element("u");
    let invalid = tree.insert_adjacent_element(host, "nowhere", u2);
    assert!(!invalid);
    assert_eq!(tree.parent(u2), None);
    let want = probe(&fixture(), "insert_adjacent_element");
    assert_eq!(want["invalid"], "SyntaxError");
    let got = json!({
        "inserted": inserted,
        "wrapper": serialize_inner(&tree, wrapper),
        // insertAdjacentElement returns null when it does not insert
        "detachedBefore": if before { json!("inserted") } else { Value::Null },
        "detachedAfter": if after { json!("inserted") } else { Value::Null },
        "invalid": "SyntaxError",
    });
    assert_eq!(got, want);
    assert_eq!(tree.parent(u), None);
}

#[test]
fn toggle_attribute_matches_chrome() {
    let mut tree = Tree::parse("");
    let el = tree.create_element("div");
    let mut sequence = Vec::new();
    for force in [None, None, Some(true), Some(true), Some(false), Some(false)] {
        let result = tree.toggle_attribute(el, "hidden", force);
        sequence.push(json!(result));
        // the fourth step reads the value instead of presence
        if sequence.len() == 7 {
            sequence.push(json!(tree.get_attribute(el, "hidden")));
        } else {
            sequence.push(json!(tree.has_attribute(el, "hidden")));
        }
    }
    assert_eq!(
        json!({ "sequence": sequence }),
        probe(&fixture(), "toggle_attribute")
    );
}

#[test]
fn names_and_namespaces_match_chrome() {
    let fixture = fixture();
    let want = probe(&fixture, "names_and_namespaces");
    let mut tree = Tree::parse("");
    let upper_units: Vec<u16> = "DiV".encode_utf16().collect();
    let upper = tree.create_element_units(&upper_units);
    let null_ns = tree.create_element_namespace(None, "thing");
    let custom = tree.create_element_namespace(Some("urn:a"), "p:thing");
    let parsed = Tree::parse("<svg><a xlink:href=\"u\"></a></svg>");
    let link = parsed.query_selector("a").unwrap();
    let names: Vec<String> = parsed
        .attributes(link)
        .into_iter()
        .map(|(n, _)| n)
        .collect();
    let mut prefixes = Vec::new();
    parsed.for_each_attr_full(link, |prefix, _, _| prefixes.push(prefix.to_owned()));
    let missing = tree.create_element("div");
    let got = json!({
        "upperLocalName": tree.local_name(upper),
        "upperTagName": String::from_utf16(&tree.tag_name_utf16(upper).unwrap()).unwrap(),
        "nullNamespaceURI": tree.namespace_uri(null_ns),
        "nullTagName": tree.tag_name(null_ns),
        "customTagName": tree.tag_name(custom),
        "customPrefix": tree.prefix(custom),
        "parsedAttributeNames": names,
        "parsedAttributePrefix": prefixes[0],
        "parsedAttributeNamespace": parsed.get_attribute_ns(link, Some("http://www.w3.org/1999/xlink"), "href").map(|_| "http://www.w3.org/1999/xlink"),
        "getAttributeNSMissing": tree.get_attribute_ns(missing, Some("urn:x"), "a"),
    });
    assert_eq!(got, want);
}

#[test]
fn of_type_pseudo_classes_compare_namespaces_like_chrome() {
    let mut tree = Tree::parse("");
    let host = tree.create_element("div");
    let kids = [
        tree.create_element("rect"),
        tree.create_element_namespace(Some("http://www.w3.org/2000/svg"), "rect"),
        tree.create_element_namespace(Some("urn:a"), "x"),
        tree.create_element_namespace(Some("urn:b"), "x"),
        tree.create_element_namespace(Some("urn:a"), "x"),
        tree.create_element_namespace(None, "x"),
    ];
    for kid in kids {
        tree.append_child(host, kid);
    }
    let got = json!({
        "firstOfType": kids.iter().map(|&k| tree.matches(k, ":first-of-type")).collect::<Vec<_>>(),
        "lastOfType": kids.iter().map(|&k| tree.matches(k, ":last-of-type")).collect::<Vec<_>>(),
    });
    assert_eq!(got, probe(&fixture(), "of_type_namespaces"));
}

#[test]
fn serialization_matches_chrome() {
    let mut tree = Tree::parse("");
    let div = tree.create_element("div");
    tree.set_inner_html(div, "<a title=\"a&nbsp;b\">c&nbsp;d</a>");
    let holder = tree.create_element("div");
    let comment = tree.create_comment("c");
    let pi = tree.create_processing_instruction("t", "d");
    tree.append_child(holder, comment);
    tree.append_child(holder, pi);
    let got = json!({
        "nbsp": serialize_inner(&tree, div),
        "commentAndPi": serialize_inner(&tree, holder),
    });
    assert_eq!(got, probe(&fixture(), "serialization"));
}

#[test]
fn remove_attribute_matches_chrome() {
    let mut tree = Tree::parse("");
    let el = tree.create_element("div");
    tree.set_attribute(el, "a", "1");
    tree.set_attribute_ns(el, Some("urn:x"), "p:b", "2");
    let missing: Vec<u16> = "missing".encode_utf16().collect();
    let prefixed: Vec<u16> = "p:b".encode_utf16().collect();
    tree.remove_attribute_units(el, &missing);
    tree.remove_attribute_units(el, &prefixed);
    let names: Vec<String> = tree.attributes(el).into_iter().map(|(n, _)| n).collect();
    assert_eq!(
        json!({ "names": names }),
        probe(&fixture(), "remove_attribute")
    );
}

#[test]
fn contextual_fragment_reads_is_at_creation_like_chrome() {
    let mut tree = Tree::parse("<body></body>");
    let body = tree.query_selector("body").unwrap();
    let units: Vec<u16> = "<div is=\"x-y\"></div><p></p>".encode_utf16().collect();
    let fragment = tree.create_contextual_fragment_utf16(body, &units, true);
    let children = tree.children(fragment);
    let got = json!({
        "isDefined": tree.matches(children[0], ":defined"),
        "plainDefined": tree.matches(children[1], ":defined"),
    });
    assert_eq!(got, probe(&fixture(), "contextual_fragment_is"));
}
